int main() {
    int n;
    cin >> n;
    vector<int> a(n);
    for (auto &x : a) cin >> x;
    sort(a.begin(), a.end());
    int d = INT_MAX;
    for (int i = 0; i + 1 < n; i++) d = min(d, a[i + 1] - a[i]);
    long long pairs = 0;
    if (d == 0) {
        // 相同值的任兩個都成對：C(c, 2)
        int i = 0;
        while (i < n) {
            int j = i;
            while (j < n && a[j] == a[i]) j++;
            long long c = j - i;
            pairs += c * (c - 1) / 2;
            i = j;
        }
    } else {
        for (int i = 0; i + 1 < n; i++)
            if (a[i + 1] - a[i] == d) pairs++;
    }
    cout << d << ' ' << pairs << '\n';
}

