#include <bits/stdc++.h>
using namespace std;
using ll = long long;
const ll MOD = 1000000007;

int main() {
    string s;
    cin >> s;
    int n = s.size();
    // nxt[i][c]：位置 i 之後（含 i）第一個字母 c；prv[i][c]：i 之前（含 i）最後一個
    vector<array<int, 4>> nxt(n + 1), prv(n);
    nxt[n] = {n, n, n, n};
    for (int i = n - 1; i >= 0; i--) {
        nxt[i] = nxt[i + 1];
        nxt[i][s[i] - 'a'] = i;
    }
    for (int i = 0; i < n; i++) {
        if (i) prv[i] = prv[i - 1];
        else prv[i] = {-1, -1, -1, -1};
        prv[i][s[i] - 'a'] = i;
    }
    vector<vector<ll>> f(n, vector<ll>(n, 0));
    for (int len = 1; len <= n; len++) {
        for (int i = 0; i + len - 1 < n; i++) {
            int j = i + len - 1;
            if (i == j) {
                f[i][j] = 1;
                continue;
            }
            ll inner = (i + 1 <= j - 1) ? f[i + 1][j - 1] : 0;
            ll v;
            if (s[i] != s[j]) {
                v = f[i + 1][j] + f[i][j - 1] - inner;
            } else {
                int c = s[i] - 'a';
                int lo = nxt[i + 1][c], hi = prv[j - 1][c];
                if (lo > hi) v = 2 * inner + 2;
                else if (lo == hi) v = 2 * inner + 1;
                else v = 2 * inner - f[lo + 1][hi - 1];
            }
            f[i][j] = ((v % MOD) + MOD) % MOD;
        }
    }
    cout << f[0][n - 1] % MOD << '\n';
    return 0;
}
